197	     * Emits the immutable structured {@code OWNER_CREATED} event to the {@code AUDIT} logger, in
198	     * addition to the human-readable audit line. The event is a JSON object
199	     * {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}} where {@code seq}
200	     * is a monotonically increasing integer across every create (see {@link #EVENT_SEQ}).
201	     *
202	     * <p>The event carries the owner's <em>current</em> primary identifier under
203	     * {@code customerCode}; see {@link #primaryIdentifier(Owner)} — the single place that decides
204	     * which field is the primary identifier, so a later unification into a {@code memberId} changes
205	     * only that method and the event automatically carries the new value.
206	     *
207	     * @param owner the just-created, already-persisted owner
208	     */
209	    private static void emitOwnerCreatedEvent(Owner owner) {
210	        long seq = EVENT_SEQ.incrementAndGet();
211	        String event = "{"
212	            + "\"seq\":" + seq
213	            + ",\"ownerId\":" + owner.getId()
214	            + ",\"customerCode\":" + jsonString(primaryIdentifier(owner))
215	            + ",\"membershipLevel\":" + owner.getMembershipLevel()
216	            + ",\"event\":\"OWNER_CREATED\""
217	            + "}";
