234	    /**
235	     * Renders {@code value} as a JSON string literal (quoted and escaped), or the JSON {@code null}
236	     * literal when {@code value} is {@code null}.
237	     *
238	     * @param value the string to render, possibly {@code null}
239	     * @return a JSON string literal, or {@code null}
240	     */
241	    private static String jsonString(String value) {
242	        if (value == null) {
243	            return "null";
244	        }
245	        StringBuilder sb = new StringBuilder(value.length() + 2);
246	        sb.append('"');
247	        for (int i = 0; i < value.length(); i++) {
248	            char c = value.charAt(i);
249	            switch (c) {
250	                case '"' -> sb.append("\\\"");
251	                case '\\' -> sb.append("\\\\");
252	                case '\n' -> sb.append("\\n");
253	                case '\r' -> sb.append("\\r");
254	                case '\t' -> sb.append("\\t");
255	                default -> {
256	                    if (c < 0x20) {
257	                        sb.append(String.format("\\u%04x", (int) c));
258	                    }
259	                    else {
260	                        sb.append(c);
261	                    }
262	                }
263	            }
264	        }
265	        sb.append('"');
266	        return sb.toString();
267	    }
