351	    /**
352	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
353	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
354	     * Validation already rejects {@code null} values and the pattern-constrained fields
355	     * when blank, but {@code address} and {@code city} have no pattern, so a
356	     * whitespace-only value would otherwise slip through.
357	     *
358	     * @param ownerFieldsDto the submitted owner fields
359	     * @throws RequiredFieldsMissingException if any required field is missing or blank
360	     */
361	    /**
362	     * Common street-type abbreviations expanded during address normalization. Keys are the
363	     * upper-cased abbreviation tokens; values are their canonical expansions.
364	     */
365	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
366	        "ST", "STREET",
367	        "RD", "ROAD",
368	        "AVE", "AVENUE");
369	
370	    /**
371	     * Normalizes the submitted address on create, accepting either the structured form
372	     * ({@code addressLine1} plus an optional {@code addressLine2}) or the flat {@code address}
373	     * form retained for backward compatibility. Each supplied field is canonicalized the same way
374	     * (trimmed, internal whitespace collapsed to a single space, upper-cased, and common
375	     * street-type abbreviations expanded — see {@link #ADDRESS_ABBREVIATIONS}), and the normalized
376	     * values are written back onto the request.
377	     *
378	     * <p>The structured fields are preferred when present: when a non-blank {@code addressLine1} is
379	     * supplied, the flat {@code address} is set to the composed value — the normalized
380	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended
381	     * when an {@code addressLine2} is present — otherwise it keeps the normalized flat value. The
382	     * composed {@code address} is therefore persisted, echoed back, and used by everything that
383	     * reads the flat address. A blank/absent value in every form leaves {@code address} blank so the
384	     * required-field check can report it as missing.
385	     *
386	     * @param ownerFieldsDto the submitted owner fields
387	     */
388	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
389	        String addressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
390	        String addressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
391	        String flat = normalizeAddress(ownerFieldsDto.getAddress());
392	        ownerFieldsDto.setAddressLine1(addressLine1);
393	        ownerFieldsDto.setAddressLine2(addressLine2);
394	        String composed;
395	        if (addressLine1 != null && !addressLine1.isBlank()) {
396	            composed = (addressLine2 != null && !addressLine2.isBlank())
397	                ? addressLine1 + " " + addressLine2
398	                : addressLine1;
399	        }
400	        else {
401	            composed = flat;
402	        }
403	        ownerFieldsDto.setAddress(composed);
404	    }
405	
406	    /**
407	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
408	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
409	     * expanded to its full form. A {@code null} value is returned unchanged.
410	     *
411	     * @param raw the address to canonicalize, possibly {@code null}
412	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
413	     */
414	    private static String normalizeAddress(String raw) {
415	        if (raw == null) {
416	            return null;
417	        }
418	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
419	        if (collapsed.isEmpty()) {
420	            return collapsed;
421	        }
422	        String[] tokens = collapsed.split(" ");
423	        StringBuilder sb = new StringBuilder(collapsed.length());
424	        for (int i = 0; i < tokens.length; i++) {
425	            if (i > 0) {
426	                sb.append(' ');
427	            }
428	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
429	        }
430	        return sb.toString();
431	    }
432	
433	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
434	        List<String> errors = new ArrayList<>();
435	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
436	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
437	        requireText("address", ownerFieldsDto.getAddress(), errors);
438	        requireText("city", ownerFieldsDto.getCity(), errors);
439	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
440	        if (!errors.isEmpty()) {
441	            throw new RequiredFieldsMissingException(errors);
442	        }
443	    }
444	
445	    private static void requireText(String field, String value, List<String> errors) {
446	        if (value == null || value.isBlank()) {
447	            errors.add(field);
448	        }
449	    }
450	
451	    /**
452	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
453	     * postcode against the owner's city. A region absent from this table (i.e. a city whose region
454	     * is {@code 'UNKNOWN'}) imposes no range, so any 4-digit postcode is accepted there.
455	     */
456	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
457	        "NSW", new int[] {2000, 2099},
458	        "VIC", new int[] {3000, 3099},
459	        "QLD", new int[] {4000, 4099});
