461	    /**
462	     * Validates the submitted {@code postcode} only when present. The field is optional, so a
463	     * {@code null} value is accepted. When present it has already been constrained to four digits
464	     * by Bean Validation; here it is additionally checked against the owner's city: for a city
465	     * whose region is known (see {@link org.springframework.samples.petclinic.mapper.LocalityLookup}),
466	     * the postcode must fall within that region's inclusive range
467	     * ({@link #REGION_POSTCODE_RANGE}); a city with no known region accepts any 4-digit value.
468	     *
469	     * @param ownerFieldsDto the submitted owner fields (city already validated as present)
470	     * @throws InvalidPostcodeException with a 400 status if the postcode is out of range for the
471	     *                                  city's region
472	     */
473	    private static void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
474	        String postcode = ownerFieldsDto.getPostcode();
475	        if (postcode == null) {
476	            return;
477	        }
478	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
479	            .regionFor(ownerFieldsDto.getCity());
480	        int[] range = REGION_POSTCODE_RANGE.get(region);
481	        if (range == null) {
482	            return;
483	        }
484	        int value = Integer.parseInt(postcode);
485	        if (value < range[0] || value > range[1]) {
486	            throw new InvalidPostcodeException(postcode);
