492	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
493	     * and echoed back in that form.
494	     *
495	     * @param ownerFieldsDto the submitted owner fields
496	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
497	     *                                        valid E.164 number
498	     */
499	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
500	        String e164 = toE164(ownerFieldsDto.getTelephone());
501	        if (e164 == null) {
502	            throw new RequiredFieldsMissingException(List.of("telephone"));
503	        }
