507	    /**
508	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
509	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
510	     * and country code are present they are kept; otherwise country code {@code '+61'} is
511	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
512	     * must contain 8 to 15 digits after the {@code '+'}, and for the recognised country codes
513	     * the national-number length must match the country: {@code '+61'} (Australia) requires
514	     * exactly 9 national digits and {@code '+1'} (NANP) requires exactly 10.
515	     *
516	     * @param raw the submitted telephone, possibly {@code null}
517	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
518	     */
519	    private static String toE164(String raw) {
520	        if (raw == null) {
521	            return null;
522	        }
523	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
524	        String digits;
525	        if (cleaned.startsWith("+")) {
526	            digits = cleaned.substring(1);
527	        } else {
528	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
529	            digits = "61" + national;
530	        }
531	        if (!digits.matches("[0-9]{8,15}")) {
532	            return null;
533	        }
534	        if (digits.startsWith("61")) {
535	            // Australia: exactly 9 national digits after the '+61' country code.
536	            if (digits.length() - 2 != 9) {
537	                return null;
538	            }
539	        } else if (digits.startsWith("1")) {
540	            // NANP: exactly 10 national digits after the '+1' country code.
541	            if (digits.length() - 1 != 10) {
542	                return null;
543	            }
544	        }
545	        return "+" + digits;
546	    }
