558	    /**
559	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
560	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
561	     * the parts may contain whitespace or a second {@code @}.
562	     */
563	    private static final Pattern EMAIL_PATTERN =
564	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
565	
566	    /**
567	     * Disposable email domains that are not accepted for an owner's email. A create whose email
568	     * domain (the part after the {@code '@'}, compared case-insensitively) is on this blocklist is
569	     * rejected. Kept lower-cased to match the normalized email.
570	     */
571	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
572	        "mailinator.com",
573	        "tempmail.com",
574	        "guerrillamail.com");
575	
576	    /**
577	     * Normalizes the submitted email when present: the value is trimmed, required to be a
578	     * syntactically valid address, required not to use a disposable-email domain, and written back
579	     * lower-cased so it is persisted and echoed back in canonical form. A {@code null} email is
580	     * left untouched — the field is optional.
581	     *
582	     * @param ownerFieldsDto the submitted owner fields
583	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically
584	     *                               valid, or its domain is on the disposable-domain blocklist
585	     */
586	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
587	        String email = ownerFieldsDto.getEmail();
588	        if (email == null) {
589	            return;
590	        }
591	        String trimmed = email.strip();
592	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
593	            throw new InvalidEmailException(email);
594	        }
595	        String normalized = trimmed.toLowerCase(Locale.ROOT);
596	        String domain = normalized.substring(normalized.indexOf('@') + 1);
597	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
598	            throw new InvalidEmailException(email);
599	        }
600	        ownerFieldsDto.setEmail(normalized);
601	    }
