621	    /**
622	     * Establishes the effective registration date on create and rolls it onto a business day.
623	     * When the client does not supply a {@code registrationDate} it defaults to the server's
624	     * current date; the resulting date (supplied or defaulted) is then rolled forward to the
625	     * next Monday when it falls on a Saturday or Sunday (see {@link #toBusinessDay}). The
626	     * adjusted value is written back onto the request so it is persisted, echoed back in ISO
627	     * 'YYYY-MM-DD' format, and used by every value derived from the registration date (such as
628	     * the membership number's year segment and the daily create-limit).
629	     *
630	     * @param ownerFieldsDto the submitted owner fields
631	     */
632	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
633	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
634	        if (effective == null) {
635	            effective = LocalDate.now();
636	        }
637	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
638	    }
