640	    /**
641	     * Fixed public holidays that the business-day roll skips. A registration date that lands on
642	     * one of these dates is advanced to the next non-holiday business day (see
643	     * {@link #toBusinessDay}).
644	     */
645	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
646	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
647	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
648	        LocalDate.parse("2026-12-28"));
649	
650	    /**
651	     * Rolls a date forward to the next business day: any date that falls on a Saturday, a Sunday
652	     * or a listed public holiday is advanced one day at a time until it lands on a weekday that is
653	     * not a public holiday; any other date is returned unchanged.
654	     *
655	     * @param date the date to adjust
656	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday
657	     *         business day
658	     */
659	    private static LocalDate toBusinessDay(LocalDate date) {
660	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
661	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
662	            || PUBLIC_HOLIDAYS.contains(date)) {
663	            date = date.plusDays(1);
664	        }
665	        return date;
666	    }
