668	    /**
669	     * Assigns the owner's {@code customerCode} on create, formatted
670	     * {@code '<REGION>-<HASH8>'} where REGION is the region derived from the owner's postcode
671	     * (preferring the postcode range, falling back to the city — the same derivation that yields
672	     * the owner's {@code locality}, see
673	     * {@link org.springframework.samples.petclinic.mapper.LocalityLookup#regionFor(String, String)}),
674	     * and HASH8 is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
675	     * already-normalized (E.164) {@code telephone} concatenated with its {@code lastName} — e.g.
676	     * {@code 'NSW-A1B2C3D4'}. There is no per-city sequence: two owners in the same region share a
677	     * customer code only when their normalized telephone and last name both match.
678	     *
679	     * <p>When the computed customer code collides with an existing owner's {@code customerCode},
680	     * it is de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
681	     * makes it unique among the existing owners, so distinct owners always receive distinct codes.
682	     *
683	     * @param owner the owner being created (with its {@code postcode}, {@code city},
684	     *              {@code telephone} and {@code lastName} already set)
685	     */
686	    private void assignCustomerCode(Owner owner) {
687	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
688	            .regionFor(owner.getPostcode(), owner.getCity());
689	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
690	            .substring(0, 8).toUpperCase(Locale.ROOT);
691	        String base = region + "-" + hash8;
692	        Set<String> existing = this.clinicService.findAllOwners().stream()
693	            .map(Owner::getCustomerCode)
694	            .filter(Objects::nonNull)
695	            .collect(Collectors.toSet());
696	        String customerCode = base;
697	        for (int n = 2; existing.contains(customerCode); n++) {
698	            customerCode = base + "-" + n;
699	        }
700	        owner.setCustomerCode(customerCode);
701	    }
