773	        String householdId = owner.getHouseholdId();
774	        Integer maxLevel = this.clinicService.findAllOwners().stream()
775	            .filter(other -> !other.isDeleted())
776	            .filter(other -> householdId != null && householdId.equals(other.getHouseholdId()))
777	            .map(Owner::getMembershipLevel)
778	            .filter(Objects::nonNull)
779	            .max(Integer::compareTo)
780	            .orElse(null);
