844	     * {@link #rejectDuplicateIdentity}, so this owner is not a hard duplicate. A declared household
845	     * member (one that opted in via {@code sharesHousehold}) is never flagged: it is an
846	     * acknowledged member of the household, not a suspected duplicate, so {@code possibleDuplicate}
847	     * is {@code false}. Otherwise it is a <em>possible</em> duplicate when an existing owner shares
848	     * its {@code soundex(lastName)} (see {@link Owner#soundex}) and its {@code postcode} but has a
849	     * <em>different</em> {@code identityKey} (so it was not already rejected as a hard duplicate —
850	     * typically a different telephone or email): {@code possibleDuplicate} is set {@code true} and
851	     * {@code possibleDuplicateOf} to that owner's id (the earliest such owner by id when several
852	     * match). Otherwise {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf}
853	     * is left unset. The scan is taken over the existing owners before this one is persisted.
854	     *
855	     * @param owner the owner being created (with its {@code lastName}, {@code postcode},
856	     *              already-normalized {@code telephone} and {@code email} set)
857	     * @param declaredHouseholdMember whether the request opted in via {@code sharesHousehold}
858	     */
859	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
860	        if (declaredHouseholdMember) {
861	            owner.setPossibleDuplicate(false);
862	            owner.setPossibleDuplicateOf(null);
863	            return;
864	        }
865	        String lastName = owner.getLastName();
866	        String postcode = owner.getPostcode();
867	        Integer matchId = null;
868	        if (lastName != null && postcode != null) {
869	            String soundex = Owner.soundex(lastName);
870	            String identityKey = owner.getIdentityKey();
871	            matchId = this.clinicService.findAllOwners().stream()
872	                .filter(existing -> soundex.equals(Owner.soundex(existing.getLastName())))
873	                .filter(existing -> postcode.equals(existing.getPostcode()))
874	                .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
875	                .map(Owner::getId)
876	                .filter(id -> id != null)
877	                .min(Integer::compareTo)
878	                .orElse(null);
879	        }
880	        owner.setPossibleDuplicate(matchId != null);
881	        owner.setPossibleDuplicateOf(matchId);
882	    }
