884	    /**
885	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
886	     *
887	     * @param value the string to hash
888	     * @return the 64-character lower-case hex digest
889	     */
890	    private static String sha256Hex(String value) {
891	        try {
892	            byte[] digest = MessageDigest.getInstance("SHA-256")
893	                .digest(value.getBytes(StandardCharsets.UTF_8));
894	            StringBuilder sb = new StringBuilder(digest.length * 2);
895	            for (byte b : digest) {
896	                sb.append(String.format("%02x", b));
897	            }
898	            return sb.toString();
899	        }
900	        catch (NoSuchAlgorithmException e) {
901	            throw new IllegalStateException("SHA-256 not available", e);
902	        }
903	    }
