906	     * Rejects a create whose whole derived {@code identityKey} already equals that of an existing
907	     * owner (owners flagged deleted are ignored). The key is the SHA-256 hex of
908	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} (see
909	     * {@link Owner#identityKey}), and a create is a duplicate only when its <em>whole</em> key
910	     * matches an existing owner's. Because the telephone is part of the key, two owners sharing a
911	     * last name and postcode but with different telephones have different identity keys and are
912	     * both allowed (the second is flagged a soft match, see {@link #assignPossibleDuplicate}); only
913	     * an exact full-key match is rejected. The submitted telephone and email have already been
914	     * normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}, and each existing
915	     * owner's key is computed the same way so differing input formats collapse to the same value.
916	     *
917	     * @param ownerFieldsDto the submitted owner fields (telephone and email already normalized)
918	     * @throws DuplicateIdentityException with a 409 status if another owner already has the same
919	     *                                    whole identity key
920	     */
921	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
922	        String identityKey = Owner.identityKey(ownerFieldsDto.getTelephone(),
923	            ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
924	        boolean duplicate = this.clinicService.findAllOwners().stream()
925	            .filter(owner -> !owner.isDeleted())
926	            .map(Owner::getIdentityKey)
927	            .anyMatch(identityKey::equals);
928	        if (duplicate) {
929	            throw new DuplicateIdentityException(identityKey);
930	        }
931	    }
