942	     * before this owner is persisted.
943	     *
944	     * @param city the submitted city
945	     * @throws CityAtCapacityException with a 409 status if the city is already at capacity
946	     */
947	    private void rejectCityAtCapacity(String city) {
948	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
949	            throw new CityAtCapacityException(city);
950	        }
951	    }
952	
953	    /**
954	     * The number of owners in a city at which a create begins warning that the city is approaching
955	     * its {@link #CITY_CAPACITY} limit. A create is flagged with {@code capacityWarning} once the
956	     * city already holds this many owners (up to, but not including, the hard limit).
957	     */
958	    private static final long CAPACITY_WARNING_THRESHOLD = 40;
959	
960	    /**
961	     * Assigns the owner's {@code capacityWarning} on create: {@code true} when the owner's city
962	     * already holds between {@link #CAPACITY_WARNING_THRESHOLD} and {@link #CITY_CAPACITY} minus one
963	     * owners (inclusive) — i.e. it is approaching, but has not reached, the hard capacity limit —
964	     * otherwise {@code false}. The count is taken over the existing owners before this one is
965	     * persisted, using the same case-insensitive city comparison as {@link #rejectCityAtCapacity}.
966	     * The hard rejection at {@link #CITY_CAPACITY} is enforced separately, so a warned create is
967	     * still allowed.
968	     *
969	     * @param owner the owner being created (with its {@code city} already set)
970	     */
971	    private void assignCapacityWarning(Owner owner) {
972	        long count = countOwnersInCity(owner.getCity());
973	        owner.setCapacityWarning(count >= CAPACITY_WARNING_THRESHOLD && count < CITY_CAPACITY);
974	    }
975	
976	    /**
977	     * Counts the existing owners whose {@code city} equals the given city, compared
978	     * case-insensitively (matching {@link #assignCustomerCode}). The count is taken over the
979	     * current owners, before any in-flight create is persisted.
980	     *
981	     * @param city the city to count owners for
982	     * @return the number of existing owners in that city
983	     */
984	    private long countOwnersInCity(String city) {
985	        return this.clinicService.findAllOwners().stream()
986	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
987	            .count();
988	    }
989	
990	    /**
991	     * The maximum number of owners permitted to be created in a single day. A create is
992	     * rejected once this many owners already carry today's {@code registrationDate}.
993	     */
994	    private static final long DAILY_LIMIT = 100;
995	
996	    /**
997	     * Rejects a create once {@link #DAILY_LIMIT} or more owners already carry the given adjusted
998	     * business day as their {@code registrationDate}. The day counted against is this create's
999	     * effective registration date after the business-day roll (see {@link #defaultRegistrationDate}),
1000	     * so owners are counted per adjusted business day. The count is taken before this owner is
1001	     * persisted.
1002	     *
1003	     * @param businessDay the effective, business-day-adjusted registration date of this create
1004	     * @throws DailyOwnerLimitExceededException with a 429 status if the day is already at the limit
1005	     */
1006	    private void rejectDailyLimit(LocalDate businessDay) {
1007	        long count = this.clinicService.findAllOwners().stream()
1008	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
1009	            .count();
1010	        if (count >= DAILY_LIMIT) {
1011	            throw new DailyOwnerLimitExceededException(businessDay);
1012	        }
1013	    }
1014	
1015	    /**
1016	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
1017	     * every internal run of whitespace is collapsed to a single space, and the result is
1018	     * lower-cased. A {@code null} value collapses to the empty string.
1019	     *
1020	     * @param value the value to canonicalize, possibly {@code null}
1021	     * @return the collapsed, lower-cased value
1022	     */
1023	    private static String collapse(String value) {
1024	        if (value == null) {
1025	            return "";
1026	        }
1027	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
1028	    }
1029	
1030	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
1031	    @Override
1032	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
1033	        Owner owner = this.clinicService.findOwnerById(ownerId);
1034	        if (owner != null) {
1035	            Pet pet = owner.getPet(petId);
1036	            if (pet != null) {
1037	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
1038	            }
1039	        }
1040	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
1041	    }
1042	}
